#include "lsm.hpp"
#include <iostream>
#include <iomanip>

int main() {
    // Test parameters
    double S0 = 40.0;      // Spot price
    double K = 40.0;       // Strike price
    double r = 0.05;       // Risk-free rate
    double sigma = 0.2;    // Volatility
    double T = 1.0;        // Time to maturity
    int steps = 50;        // Number of time steps
    std::int64_t paths = 100000;  // Number of paths
    std::uint64_t seed = 42;   // Random seed

    std::cout << "Testing Longstaff-Schwartz American Put Pricer\n";
    std::cout << "Parameters:\n";
    std::cout << "S0 = " << S0 << ", K = " << K << ", r = " << r << ", sigma = " << sigma << ", T = " << T << "\n";
    std::cout << "Steps = " << steps << ", Paths = " << paths << "\n\n";

    mc::McResult result = mc::american_put_lsm(S0, K, r, sigma, T, steps, paths, seed);

    std::cout << "Result:\n";
    std::cout << "Price = " << std::fixed << std::setprecision(6) << result.price << "\n";
    std::cout << "Standard Error = " << std::scientific << std::setprecision(2) << result.std_error << "\n";

    // Test with a larger spot price to verify scale invariance
    std::cout << "\nTesting with larger spot price:\n";
    S0 = 40000.0;
    result = mc::american_put_lsm(S0, K, r, sigma, T, steps, paths, seed);
    std::cout << "Price = " << std::fixed << std::setprecision(6) << result.price << "\n";
    std::cout << "Standard Error = " << std::scientific << std::setprecision(2) << result.std_error << "\n";

    return 0;
}

